32		if !ok {
33			t.Fatalf("forged effective inputs %v overflow; choose a non-overflowing sequence", effective)
34		}
35		r.EffectiveValues = append([]int64(nil), effective...)
36		r.Archive.EffectiveValues = append([]int64(nil), effective...)
