// 依赖作业的成功归档数值被篡改时，重开后该作业失败，仍在排队的下游
// 沿用既有上游失败处理级联失败，不能继续使用错误总和计算。
func TestReopenForgedUpstreamFailsQueuedDownstream(t *testing.T) {
